testo:
{
 "genere": "prevedi",
 "titolo": "Cosa restituisce?",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted


func run() -> bool:
	var save_data := {"unlocked_levels": [1, 2, 3]}
	var levels: Array = save_data.get("unlocked_levels", [1])
	return 4 in levels
",
   "domanda": "`run()` restituisce `true` o `false`?",
   "spiegazione": "`save_data` contiene l'array `[1, 2, 3]` associato a "unlocked_levels". Il numero `4` non è presente nell'array, quindi l'espressione `4 in levels` restituisce `false`."
  },
  {
   "codice": "extends RefCounted


func run() -> int:
	var levels_unlocked := 2
	var next_level := 3
	if next_level > levels_unlocked + 1:
		return levels_unlocked
	else:
		return next_level
",
   "domanda": "Che numero restituisce `run()`?",
   "spiegazione": "`levels_unlocked + 1` fa 3. La condizione chiede se `next_level` (che è 3) è maggiore di 3: poiché 3 non è maggiore di 3, il controllo passa all' `else` che restituisce `next_level` (3)."
  },
  {
   "codice": "extends RefCounted


func run() -> String:
	var scenes := {
		"menu": "res://ui/main_menu.tscn",
		"game": "res://levels/level_1.tscn"
	}
	var current := "menu"
	current = "game" if current == "menu" else "menu"
	return scenes.get(current, "")
",
   "domanda": "Che testo restituisce `run()`?",
   "spiegazione": "`current` parte come "menu". L'assegnazione condizionale imposta `current` a "game" perché la condizione `current == "menu"` è vera. Successivamente `scenes.get("game")` restituisce il percorso della scena di gioco."
  },
  {
   "codice": "extends RefCounted


func run() -> int:
	var is_paused := true
	var score := 50
	if is_paused:
		score += 10
	return score
",
   "domanda": "Quanto vale `score` alla fine?",
   "spiegazione": "`is_paused` è `true`, quindi il blocco `if` viene eseguito e somma 10 a `score`, portandolo da 50 a 60."
  },
  {
   "codice": "extends RefCounted


func run() -> int:
	var json_string := '{"level": 3, "score": 450}'
	var json := JSON.new()
	var error := json.parse(json_string)
	if error == OK:
		var data: Dictionary = json.get_data()
		return data.get("level", 1)
	return 0
",
   "domanda": "Che numero restituisce `run()`?",
   "spiegazione": "`json.parse()` legge correttamente la stringa e restituisce `OK`. Il dizionario estratto contiene la chiave "level" con valore `3`, che viene restituita."
  }
 ]
}
